3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	import net.officefloor.plugin.variable.Out;
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * Step of {@code POST /api/owners} that resolves the EFFECTIVE registration date and publishes it
13	 * for the later steps.
14	 *
15	 * <p>The effective date is the one supplied in the request body, or the server's current date when
16	 * the request omits one. Because a registration must fall on a business day, a date that lands on a
17	 * Saturday, Sunday or listed public holiday is rolled forward to the next non-holiday business day —
18	 * this applies whether the date was supplied or defaulted.
19	 *
20	 * <p>Publishing the adjusted date once here keeps every value derived from it consistent: the daily
21	 * create-limit ({@link EnsureDailyLimit}) counts owners per this adjusted business day, the owner is
22	 * stored with it ({@link DefaultOwnerRegistrationDate}) and the membership number's year segment is
23	 * therefore taken from the adjusted date.
24	 */
25	public class ResolveRegistrationDate {
26	
27	    /** Fixed public holidays that a registration date must roll past, like a weekend. */
28	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
29	            LocalDate.of(2026, 1, 1),
30	            LocalDate.of(2026, 1, 26),
31	            LocalDate.of(2026, 4, 25),
32	            LocalDate.of(2026, 12, 25),
33	            LocalDate.of(2026, 12, 28));
34	
35	    public void service(@Val OwnerFieldsDto request, Out<LocalDate> registrationDate) {
36	        LocalDate effective = request.getRegistrationDate() != null
37	                ? request.getRegistrationDate() : LocalDate.now();
38	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY
39	                || effective.getDayOfWeek() == DayOfWeek.SUNDAY
40	                || PUBLIC_HOLIDAYS.contains(effective)) {
41	            effective = effective.plusDays(1);
42	        }
43	        registrationDate.set(effective);
44	    }
45	}
